sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float2 center;
uniform float radius;
uniform float feather;
uniform float roundness;
uniform float darken;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float4 b = float4(blurred.eval(coord));
    float2 p = (coord / size - center) * float2(mix(1.0, size.x / size.y, roundness), 1.0) * 2.0;
    float mask = smoothstep(radius, radius + feather, length(p));
    float4 r = mix(c, b, mask);
    r = float4(r.rgb * (1.0 - darken * mask), r.a);
    return fin(c, r, opacity);
}
